 /**
  * @class SomeIpSdLayer
  * Implementation of the SOME/IP-SD protocol
  */
 class SomeIpSdLayer : public SomeIpLayer
 {
 public:
        friend class SomeIpSdEntry;

        typedef SomeIpSdEntry* EntryPtr;
        typedef std::vector<EntryPtr> EntriesVec;
        typedef SomeIpSdOption* OptionPtr;
        typedef std::vector<OptionPtr> OptionsVec;

        /**
         * A constructor that creates the layer from an existing packet raw data
         * @param[in] data A pointer to the raw data
         * @param[in] dataLen Size of the data in bytes
         * @param[in] prevLayer A pointer to the previous layer
         * @param[in] packet A pointer to the Packet instance where layer will be stored in
         */
        SomeIpSdLayer(uint8_t *data, size_t dataLen, Layer *prevLayer, Packet *packet);

        /**
         * Construct a new SomeIpSdLayer object
         * @param[in] serviceID Service ID
         * @param[in] methodID Method ID
         * @param[in] clientID Client ID
         * @param[in] sessionID Session ID
         * @param[in] interfaceVersion Interface Version
         * @param[in] type Type of the message
         * @param[in] returnCode Return Code
         * @param[in] flags Flags that shall be used in the header
         */
        SomeIpSdLayer(uint16_t serviceID, uint16_t methodID, uint16_t clientID, uint16_t sessionID,
                                  uint8_t interfaceVersion, MsgType type, uint8_t returnCode, uint8_t flags);

        /**
         * Destroy the layer object
         */
        ~SomeIpSdLayer() {}

        /**
         * Checks if given port is a SOME/IP-SD protocol port
         * @param[in] port Port to check
         * @return true if SOME/IP-SD protocol port, false if not
         */
        static bool isSomeIpSdPort(uint16_t port) { return port == 30490; }

+       /**
+       * The static method makes validation of input data
+       * @param[in] data The pointer to the beginning of byte stream of IP packet
+       * @param[in] dataLen The length of byte stream
+       * @return True if the data is valid and can represent the packet
+       */
+       static bool isDataValid(const uint8_t* data, size_t dataLen);
+
        /**
         * Get the Flags of the layer
         * @return uint8_t Flags
         */
        uint8_t getFlags() const;

        /**
         * Set the Flags of the layer
         * @param[in] flags Flags to set
         */
        void setFlags(uint8_t flags);

        /**
         * Get the number of entries in this layer
         * @return uint32_t
         */
        uint32_t getNumEntries() const;

        /**
         * Get the number of options in this layer
         * @return uint32_t
         */
        uint32_t getNumOptions() const;

        /**
         * Get the Entries from this layer
         * @return EntriesVec Vector holding pointers to the options
         */
        const EntriesVec getEntries() const;

        /**
         * Get the Options from this layer
         * @return OptionsVec Vector holding pointers to the options
         */
        const OptionsVec getOptions() const;

        /**
         * Get the Options from a specific Entry
         * @param[in] index Index of the Entry, starting with 0.
         * @return OptionsVec Vector holding pointers to the options
         */
        const OptionsVec getOptionsFromEntry(uint32_t index) const;

        /**
         * Adds a given entry to the layer and returns the index of the entry
         * @param[in] entry Pointer to the entry that shall be added to the layer
         * @return uint32_t Returns the index of the entry starting with 0
         */
        uint32_t addEntry(const SomeIpSdEntry &entry);

        /**
         * Adds an option to an entry that has already been added to the layer by using addEntry(). The option
         * is also added to the layer itself. If the option cannot by assigned to the entry, the option is not
         * copied into the layer.
         * @param[in] indexEntry Index of the entry where the option shall be added. First Entry has index 0
         * @param[in] option Pointer to the option that shall be added
         * @return True if the option could be assigned to the entry and was copied into the layer, false otherwise
         */
        bool addOptionTo(uint32_t indexEntry, const SomeIpSdOption &option);

        /**
         * Does nothing for this layer
         */
        void computeCalculateFields() {};

        /**
         * @return The string representation of the SOME/IP-SD layer
         */
        std::string toString() const;

 private:
        /**
         * @struct someipsdhdr
         * Represents an SOME/IP-SD protocol header
         */
 #pragma pack(push, 1)
        struct someipsdhdr : someiphdr
        {
                /** Flags (8 bit) */
                uint8_t flags;
                /** Reserved1 field (Bits 0-7 of 24-bits reserved field) */
                uint8_t reserved1;
                /** Reserved2 field (Bits 8-15 of 24-bits reserved field) */
                uint8_t reserved2;
                /** Reserved3 field (Bits 16-23 of 24-bits reserved field) */
                uint8_t reserved3;
        };
 #pragma pack(pop)

        uint32_t m_NumOptions;

        uint32_t countOptions();
        uint32_t findOption(const SomeIpSdOption &option);
        void addOption(const SomeIpSdOption &option);
        bool addOptionIndex(uint32_t indexEntry, uint32_t indexOffset);
        OptionPtr parseOption(SomeIpSdOption::OptionType type, size_t offset) const;

+       static size_t getLenEntries(const uint8_t* data);
        size_t getLenEntries() const;
        size_t getLenOptions() const;
        void setLenEntries(uint32_t length);
        void setLenOptions(uint32_t length);
 };

 } // namespace pcpp
 #endif /* PACKETPP_SOMEIPSD_LAYER */
diff --git a/Packet++/src/SomeIpSdLayer.cpp b/Packet++/src/SomeIpSdLayer.cpp
index de21de8a..2f599dc6 100644
--- a/Packet++/src/SomeIpSdLayer.cpp
+++ b/Packet++/src/SomeIpSdLayer.cpp
@@ -554,236 +554,251 @@ const SomeIpSdLayer::OptionsVec SomeIpSdLayer::getOptionsFromEntry(uint32_t inde
        uint8_t startIdxRun2 = hdrEntry->indexSecondOption;
        uint8_t lenRun2 = hdrEntry->nrOpt2;

        int idx = 0;

        while (remainingLen > 0)
        {
                SomeIpSdOption::someipsdhdroptionsbase *hdrOption = (SomeIpSdOption::someipsdhdroptionsbase *)(m_Data + offset);

                if (((idx >= startIdxRun1) && (idx < (startIdxRun1 + lenRun1))) ||
                        ((idx >= startIdxRun2) && (idx < (startIdxRun2 + lenRun2))))
                {
                        SomeIpSdOption::OptionType optionType = static_cast<SomeIpSdOption::OptionType>(hdrOption->type);

                        option = parseOption(optionType, offset);

                        if (option != nullptr)
                        {
                                vecOptions.push_back(std::move(option));
                        }
                }

                size_t optionLen = be16toh(hdrOption->length) + 3;
                remainingLen -= optionLen;
                offset += optionLen;
                ++idx;
        }

        return vecOptions;
 }

 bool SomeIpSdLayer::addOptionTo(uint32_t indexEntry, const SomeIpSdOption &option)
 {
        if (indexEntry >= getNumEntries())
        {
                return false;
        }

        uint32_t indexOption = findOption(option);
        bool success = addOptionIndex(indexEntry, indexOption);

        if (!success)
        {
                return false;
        }

        if (indexOption == m_NumOptions)
        {
                addOption(option);
        }

        return true;
 }

 std::string SomeIpSdLayer::toString() const
 {
        std::stringstream dataStream;

        dataStream << "SOME/IP-SD Layer, " << getNumEntries() << " entries, " << getNumOptions() << " options";

        return dataStream.str();
 }

 uint32_t SomeIpSdLayer::addEntry(const SomeIpSdEntry &entry)
 {
        size_t lenEntries = getLenEntries();
        int offsetToAddAt = sizeof(someipsdhdr) + sizeof(uint32_t) + lenEntries;

        extendLayer(offsetToAddAt, entry.getLength());

        setLenEntries(lenEntries + entry.getLength());

        memcpy(m_Data + offsetToAddAt, entry.getDataPtr(), entry.getLength());

        auto hdr = getSomeIpHeader();
        hdr->length = htobe32(be32toh(hdr->length) + (uint32_t)entry.getLength());

        return getNumEntries() - 1;
 }

+bool SomeIpSdLayer::isDataValid(const uint8_t* data, size_t dataLen)
+{
+       if (!data || dataLen < sizeof(someipsdhdr) + sizeof(uint32_t) || dataLen < sizeof(someipsdhdr) + sizeof(uint32_t) + getLenEntries(data))
+       {
+               return false;
+       }
+
+       return true;
+}
+
 uint32_t SomeIpSdLayer::countOptions()
 {
        size_t offsetOption = sizeof(someipsdhdr) + sizeof(uint32_t) + getLenEntries() + sizeof(uint32_t);
        size_t lenOptions = getLenOptions();
        uint32_t len = 0;

        uint32_t numOptions = 0;
        while (len < lenOptions)
        {
                uint32_t lenOption = be16toh(*((uint16_t *)(m_Data + offsetOption + len))) + 3 * sizeof(uint8_t);
                len += lenOption;
                ++numOptions;
        }
        return numOptions;
 }

 uint32_t SomeIpSdLayer::findOption(const SomeIpSdOption &option)
 {
        size_t offsetOption = sizeof(someipsdhdr) + sizeof(uint32_t) + getLenEntries() + sizeof(uint32_t);

        uint32_t i = 0;
        while (i < m_NumOptions)
        {
                uint32_t lenOption = be16toh(*((uint16_t *)(m_Data + offsetOption))) + 3 * sizeof(uint8_t);

                if (option.getLength() == lenOption)
                {
                        if (memcmp(m_Data + offsetOption, option.getDataPtr(), option.getLength()) == 0)
                        {
                                return i;
                        }
                }

                offsetOption += lenOption;
                ++i;
        }
        return i;
 }

 void SomeIpSdLayer::addOption(const SomeIpSdOption &option)
 {
        int offsetToAddAt = (int)getHeaderLen();

        extendLayer(offsetToAddAt, option.getLength());
        memcpy(m_Data + offsetToAddAt, option.getDataPtr(), option.getLength());

        setLenOptions(uint32_t(getLenOptions() + option.getLength()));

        auto hdr = getSomeIpHeader();
        hdr->length = htobe32(be32toh(hdr->length) + (uint32_t)option.getLength());

        ++m_NumOptions;
 }

 bool SomeIpSdLayer::addOptionIndex(uint32_t indexEntry, uint32_t indexOffset)
 {
        /* The SOME/IP-SD protocol supports two option runs. Runs meaning that two different starting indices with differing
        length can be provided. Of course, this only works if the indices in both runs are consecutive.

                So, indices like this would work:
                        1 2 3 ; 7 8

                What wouldn't work is this:
                        1 2 3 ; 7 9
                        1 3 ; 7 8
        */

        size_t offsetToAddAt = sizeof(someipsdhdr) + sizeof(uint32_t) + indexEntry*sizeof(SomeIpSdEntry::someipsdhdrentry);
        auto hdrEntry = (SomeIpSdEntry::someipsdhdrentry *)(m_Data + offsetToAddAt);

        uint8_t indexFirstOption = hdrEntry->indexFirstOption;
        uint8_t lenFirstOption = hdrEntry->nrOpt1;

        if (lenFirstOption == 0)
        {
                hdrEntry->indexFirstOption = indexOffset;
                ++hdrEntry->nrOpt1;
                return true;
        }

        if (static_cast<uint32_t>(indexFirstOption + lenFirstOption + 1) == indexOffset)
        {
                ++hdrEntry->nrOpt1;
                return true;
        }

        uint8_t indexSecondOption = hdrEntry->indexSecondOption;
        uint8_t lenSecondOption = hdrEntry->nrOpt2;

        if (lenSecondOption == 0)
        {
                hdrEntry->indexFirstOption = indexOffset;
                ++hdrEntry->nrOpt1;
                return true;
        }

        if (static_cast<uint32_t>(indexSecondOption + lenSecondOption + 1) == indexOffset)
        {
                ++hdrEntry->nrOpt2;
                return true;
        }

        return false;
 }

 SomeIpSdLayer::OptionPtr SomeIpSdLayer::parseOption(SomeIpSdOption::OptionType type, size_t offset) const
 {
        switch (type)
        {
        case SomeIpSdOption::OptionType::IPv4Endpoint:
        case SomeIpSdOption::OptionType::IPv4Multicast:
        case SomeIpSdOption::OptionType::IPv4SdEndpoint:
        {
                return new SomeIpSdIPv4Option(this, offset);
        }
        case SomeIpSdOption::OptionType::IPv6Endpoint:
        case SomeIpSdOption::OptionType::IPv6Multicast:
        case SomeIpSdOption::OptionType::IPv6SdEndpoint:
        {
                return new SomeIpSdIPv6Option(this, offset);
        }
        case SomeIpSdOption::OptionType::ConfigurationString:
        {
                return new SomeIpSdConfigurationOption(this, offset);
        }
        case SomeIpSdOption::OptionType::LoadBalancing:
        {
                return new SomeIpSdLoadBalancingOption(this, offset);
        }
        default:
                break;
        }
        return nullptr;
 }

 size_t SomeIpSdLayer::getLenEntries() const
 {
-       return be32toh(*((uint32_t *)(m_Data + sizeof(someipsdhdr))));
+       return getLenEntries(m_Data);
+}
+
+size_t SomeIpSdLayer::getLenEntries(const uint8_t* data)
+{
+       return be32toh(*((uint32_t *)(data + sizeof(someipsdhdr))));
 }

 size_t SomeIpSdLayer::getLenOptions() const
 {
        return be32toh(*((uint32_t *)(m_Data + sizeof(someipsdhdr) + sizeof(uint32_t) + getLenEntries())));
 }

 void SomeIpSdLayer::setLenEntries(uint32_t length)
 {
        *((uint32_t *)(m_Data + sizeof(someipsdhdr))) = htobe32(length);
 }

 void SomeIpSdLayer::setLenOptions(uint32_t length)
 {
        *((uint32_t *)(m_Data + sizeof(someipsdhdr) + sizeof(uint32_t) + getLenEntries())) = htobe32(length);
 }

 } // namespace pcpp
